// Package uamethod holds the contracts of Methods of the OPC UA namespace 0
// (OPC 10000-5 and the Parts that define the types), generated by
// cmd/methods from the InputArguments and OutputArguments of the Method
// declarations of the NodeSet (internal/schema/Opc.Ua.NodeSet2.xml), for the
// ObjectTypes cmd/methods/config.go selects.
//
// For each Method there is a [Method] value with the NodeIds of the Method
// declaration and of its ObjectType and the declared arguments, an Input
// and an Output structure with Pack (to the []*ua.Variant of a
// CallMethodRequest or CallMethodResult) and Unpack (from it, with the
// checks of the Call service: the number of arguments, their built-in type
// and their ValueRank), and a Call function that calls the Method with a
// client.
//
// The Methods of FileType and FileDirectoryType (OPC 10000-20 §4.2, §4.3)
// are the first: the server package serves files with them
// (server.FileObject) and package filetransfer is the client. The
// TrustListType (OPC 10000-12 §7.8.2), PubSubConfigurationType and
// PubSubKeyServiceType (OPC 10000-14 §9.1.3.7, §8.3) Methods of the server
// and of packages gds, pubsub/remote and pubsub/sks use them too.
package uamethod

import (
	"context"
	"fmt"
	"slices"
	"strings"

	"github.com/otfabric/go-opcua/ua"
)

// Method is the contract of a Method declaration: its BrowseName, the
// ObjectType it is a component of, and its arguments (Part 3 §5.7.1, the
// Argument DataType of §8.6).
type Method struct {
	// Name is the BrowseName of the Method (its namespace is that of the
	// declaration).
	Name string
	// ObjectType is the BrowseName of the ObjectType that declares the
	// Method.
	ObjectType string
	// Namespace is the URI of the namespace of the declaration; "" is
	// namespace 0 (http://opcfoundation.org/UA/).
	Namespace string
	// ID and ObjectTypeID are the numeric identifiers of the Method and its
	// ObjectType in Namespace.
	ID, ObjectTypeID uint32
	// Clause is the clause of the specification that defines the Method,
	// from the Documentation of the declaration ("OPC 10000-20 §4.2.2").
	Clause string
	// Mandatory reports the ModellingRule Mandatory of the declaration
	// (Part 3 §6.4.4.5.2): every instance of the ObjectType has the Method.
	Mandatory bool

	in, out []argument
}

// argument is a declared Argument (Part 3 §8.6) with the built-in type the
// value is encoded as (Part 6 §5.1.2).
type argument struct {
	name        string
	dataType    uint32 // in namespace 0
	valueRank   int32
	builtin     ua.TypeID // 0: any (BaseDataType)
	description string
}

// The ValueRanks of Part 3 §5.6.2.
const (
	rankScalarOrOneDimension = -3
	rankAny                  = -2
	rankScalar               = -1
	rankOneOrMoreDimensions  = 0
	rankOneDimension         = 1
)

// String returns "ObjectType.Name".
func (m *Method) String() string { return m.ObjectType + "." + m.Name }

// NodeID returns the NodeId of the Method declaration with the namespace
// index ns: 0 for namespace 0, else the index the server has for
// Namespace.
func (m *Method) NodeID(ns uint16) *ua.NodeID { return ua.NewNumericNodeID(ns, m.ID) }

// ObjectTypeNodeID returns the NodeId of the ObjectType of the Method with
// the namespace index ns.
func (m *Method) ObjectTypeNodeID(ns uint16) *ua.NodeID {
	return ua.NewNumericNodeID(ns, m.ObjectTypeID)
}

// InputArguments returns the value of the InputArguments Property of the
// declaration, nil when the Method has no input arguments. The slice and
// the Arguments are new on each call.
func (m *Method) InputArguments() []*ua.Argument { return arguments(m.in) }

// OutputArguments returns the value of the OutputArguments Property of
// the declaration, nil when the Method has no output arguments.
func (m *Method) OutputArguments() []*ua.Argument { return arguments(m.out) }

func arguments(as []argument) []*ua.Argument {
	if len(as) == 0 {
		return nil
	}
	out := make([]*ua.Argument, len(as))
	for i, a := range as {
		out[i] = &ua.Argument{
			Name:            a.name,
			DataType:        ua.NewNumericNodeID(0, a.dataType),
			ValueRank:       a.valueRank,
			ArrayDimensions: []uint32{},
			Description:     ua.NewLocalizedText(a.description),
		}
	}
	return out
}

// ArgumentError is a list of arguments that does not match the
// declaration of a Method. Status is the code the Call service gives for
// it (Part 4 §5.12.2, Table 66 in 1.05.06): Bad_ArgumentsMissing or
// Bad_TooManyArguments for the number of arguments, Bad_TypeMismatch for
// an argument of another built-in type or ValueRank.
type ArgumentError struct {
	// Method is "ObjectType.Name".
	Method string
	// Output reports an output argument, else an input argument.
	Output bool
	// Index is the position of the argument, -1 for the number of
	// arguments.
	Index int
	// Name is the name of the declared argument, "" for the number.
	Name string
	// Status is Bad_ArgumentsMissing, Bad_TooManyArguments or
	// Bad_TypeMismatch.
	Status ua.StatusCode
	// Detail says what was found.
	Detail string
}

func (e *ArgumentError) Error() string {
	kind := "input"
	if e.Output {
		kind = "output"
	}
	if e.Index < 0 {
		return fmt.Sprintf("uamethod: %s: %s arguments: %s: %v", e.Method, kind, e.Detail, e.Status)
	}
	return fmt.Sprintf("uamethod: %s: %s argument %d (%s): %s: %v", e.Method, kind, e.Index, e.Name, e.Detail, e.Status)
}

// Unwrap returns the status, so errors.Is(err, ua.StatusBadTypeMismatch)
// holds.
func (e *ArgumentError) Unwrap() error { return e.Status }

// StatusOf returns the status an error of Unpack stands for, so a Method
// handler can return it: the Status of an *ArgumentError, else
// Bad_InvalidArgument. It returns StatusOK for nil.
func StatusOf(err error) ua.StatusCode {
	if err == nil {
		return ua.StatusOK
	}
	if e, ok := err.(*ArgumentError); ok {
		return e.Status
	}
	return ua.StatusBadInvalidArgument
}

func (m *Method) argErr(output bool, i int, sc ua.StatusCode, detail string) *ArgumentError {
	e := &ArgumentError{Method: m.String(), Output: output, Index: i, Status: sc, Detail: detail}
	if output && i >= 0 {
		e.Name = m.out[i].name
	} else if i >= 0 {
		e.Name = m.in[i].name
	}
	return e
}

// count checks the number of arguments: "The size and order of this list
// matches the size and order of the input arguments defined by the input
// InputArguments Property of the Method" (Part 4 §5.12.2.2 in 1.05.06).
func (m *Method) count(output bool, args []*ua.Variant) error {
	want := len(m.in)
	if output {
		want = len(m.out)
	}
	switch {
	case len(args) < want:
		return m.argErr(output, -1, ua.StatusBadArgumentsMissing, fmt.Sprintf("%d arguments, want %d", len(args), want))
	case len(args) > want:
		return m.argErr(output, -1, ua.StatusBadTooManyArguments, fmt.Sprintf("%d arguments, want %d", len(args), want))
	}
	return nil
}

// typeName is the name of a built-in type: "Uint32" for ua.TypeIDUint32.
func typeName(t ua.TypeID) string { return strings.TrimPrefix(t.String(), "TypeID") }

// shape checks the built-in type and the ValueRank of argument i. A nil
// Variant is the null Variant.
func (m *Method) shape(output bool, args []*ua.Variant, i int) error {
	as := m.in
	if output {
		as = m.out
	}
	a := as[i]
	v := args[i]
	typ, array, dims := ua.TypeIDNull, false, 0
	if v != nil {
		typ, array, dims = v.Type(), v.IsArray(), len(v.ArrayDimensions())
	}
	if a.builtin != 0 && typ != a.builtin {
		return m.argErr(output, i, ua.StatusBadTypeMismatch, fmt.Sprintf("a %s, want a %s", typeName(typ), typeName(a.builtin)))
	}
	ok := true
	switch a.valueRank {
	case rankScalar:
		ok = !array
	case rankOneDimension:
		ok = array && dims <= 1
	case rankOneOrMoreDimensions:
		ok = array
	case rankScalarOrOneDimension:
		ok = !array || dims <= 1
	case rankAny:
	default: // n > 1 dimensions
		ok = array && dims == int(a.valueRank)
	}
	if !ok {
		return m.argErr(output, i, ua.StatusBadTypeMismatch, fmt.Sprintf("array %v with %d dimensions, want ValueRank %d", array, dims, a.valueRank))
	}
	return nil
}

// scalar returns argument i of a scalar built-in type T.
func scalar[T any](m *Method, output bool, args []*ua.Variant, i int) (T, error) {
	var zero T
	if err := m.shape(output, args, i); err != nil {
		return zero, err
	}
	x, ok := args[i].Value().(T)
	if !ok {
		return zero, m.argErr(output, i, ua.StatusBadTypeMismatch, fmt.Sprintf("a value of %T, want %T", args[i].Value(), zero))
	}
	return x, nil
}

// pointer returns argument i of a scalar built-in type that is a pointer
// in Go (NodeId, LocalizedText, ...).
func pointer[T any](m *Method, output bool, args []*ua.Variant, i int) (*T, error) {
	return scalar[*T](m, output, args, i)
}

// array returns argument i of a one-dimensional array of built-in type T.
// A null array (Part 6 §5.2.5: length -1) is nil.
func array[T any](m *Method, output bool, args []*ua.Variant, i int) ([]T, error) {
	if err := m.shape(output, args, i); err != nil {
		return nil, err
	}
	// A null array decodes as a nil slice of its type.
	if x, ok := args[i].Value().([]T); ok {
		return x, nil
	}
	return nil, m.argErr(output, i, ua.StatusBadTypeMismatch, fmt.Sprintf("a value of %T, want %T", args[i].Value(), []T(nil)))
}

// variant returns argument i as it is: BaseDataType, or a ValueRank a Go
// type does not express.
func variant(m *Method, output bool, args []*ua.Variant, i int) (*ua.Variant, error) {
	if err := m.shape(output, args, i); err != nil {
		return nil, err
	}
	return args[i], nil
}

// structure returns argument i of a structure DataType: an ExtensionObject
// whose body is a *T (Part 6 §5.2.2.15). A null ExtensionObject is nil.
func structure[T any](m *Method, output bool, args []*ua.Variant, i int) (*T, error) {
	eo, err := pointer[ua.ExtensionObject](m, output, args, i)
	if err != nil || eo == nil || eo.Value == nil {
		return nil, err
	}
	x, ok := eo.Value.(*T)
	if !ok {
		return nil, m.argErr(output, i, ua.StatusBadTypeMismatch, fmt.Sprintf("an ExtensionObject of %T, want %T", eo.Value, x))
	}
	return x, nil
}

// structures returns argument i of a one-dimensional array of a structure
// DataType; a null element is nil.
func structures[T any](m *Method, output bool, args []*ua.Variant, i int) ([]*T, error) {
	eos, err := array[*ua.ExtensionObject](m, output, args, i)
	if err != nil || eos == nil {
		return nil, err
	}
	out := make([]*T, len(eos))
	for j, eo := range eos {
		if eo == nil || eo.Value == nil {
			continue
		}
		x, ok := eo.Value.(*T)
		if !ok {
			return nil, m.argErr(output, i, ua.StatusBadTypeMismatch, fmt.Sprintf("element %d: an ExtensionObject of %T, want %T", j, eo.Value, x))
		}
		out[j] = x
	}
	return out, nil
}

// packStructures returns the Variant of an array of structures; a nil
// element is the null ExtensionObject.
func packStructures[T any](xs []*T) *ua.Variant {
	if xs == nil {
		return ua.MustVariant([]*ua.ExtensionObject(nil))
	}
	eos := make([]*ua.ExtensionObject, len(xs))
	for i, x := range xs {
		if x == nil {
			eos[i] = ua.NewExtensionObject(nil)
		} else {
			eos[i] = ua.NewExtensionObject(x)
		}
	}
	return ua.MustVariant(eos)
}

// orNull returns v, or the null Variant for nil.
func orNull(v *ua.Variant) *ua.Variant {
	if v == nil {
		return &ua.Variant{}
	}
	return v
}

// orNullObject returns eo, or the null ExtensionObject for nil.
func orNullObject(eo *ua.ExtensionObject) *ua.ExtensionObject {
	if eo == nil {
		return ua.NewExtensionObject(nil)
	}
	return eo
}

// nodeID returns n, or the null NodeId for nil (Part 3 §8.2.4: the null
// NodeId is the Numeric NodeId 0 of namespace 0).
func nodeID(n *ua.NodeID) *ua.NodeID {
	if n == nil {
		return ua.NewTwoByteNodeID(0)
	}
	return n
}

// nodeIDs returns ns with the null NodeId for each nil element; a nil
// slice stays nil (the null array).
func nodeIDs(ns []*ua.NodeID) []*ua.NodeID {
	if ns == nil {
		return nil
	}
	out := make([]*ua.NodeID, len(ns))
	for i, n := range ns {
		out[i] = nodeID(n)
	}
	return out
}

// localizedText returns t, or the null LocalizedText for nil (Part 6
// §5.2.2.14: neither a locale nor a text).
func localizedText(t *ua.LocalizedText) *ua.LocalizedText {
	if t == nil {
		return &ua.LocalizedText{}
	}
	return t
}

// Caller calls Methods: *opcua.Client is one.
type Caller interface {
	Call(ctx context.Context, req *ua.CallMethodRequest) (*ua.CallMethodResult, error)
}

// CallError is a Bad StatusCode of the result of a call (Part 4
// §5.12.2.2 in 1.05.06), with the result of each input argument when the
// server gave them.
type CallError struct {
	// Method is "ObjectType.Name".
	Method string
	// Status is the StatusCode of the CallMethodResult.
	Status ua.StatusCode
	// InputArgumentResults are the StatusCodes of the input arguments.
	InputArgumentResults []ua.StatusCode
}

func (e *CallError) Error() string { return fmt.Sprintf("uamethod: %s: %v", e.Method, e.Status) }

// Unwrap returns the status, so errors.Is(err, ua.StatusBadInvalidState)
// holds.
func (e *CallError) Unwrap() error { return e.Status }

// Call calls m on the Object obj with the input arguments in, and returns
// the output arguments as the server sent them (the generated Call
// functions unpack them). method is the NodeId of the Method to call; nil
// calls the declaration of namespace 0, which the server maps to the
// Method of obj: "the methodId is either the NodeId of the Method that is a
// component of the Object instance or the NodeId of the Method in the
// ObjectType that defines the Method" (Part 4 §5.12.2.2 in 1.05.06). A Bad
// result is a *CallError.
func (m *Method) Call(ctx context.Context, c Caller, obj, method *ua.NodeID, in []*ua.Variant) ([]*ua.Variant, error) {
	if method == nil {
		if m.Namespace != "" {
			return nil, fmt.Errorf("uamethod: %s: the NodeId of the Method is required outside namespace 0", m)
		}
		method = m.NodeID(0)
	}
	res, err := c.Call(ctx, &ua.CallMethodRequest{ObjectID: obj, MethodID: method, InputArguments: in})
	if err != nil {
		return nil, fmt.Errorf("uamethod: %s: %w", m, err)
	}
	if res == nil {
		return nil, fmt.Errorf("uamethod: %s: no result: %w", m, ua.StatusBadUnknownResponse)
	}
	// The Severity is the two highest bits of a StatusCode: 10 is Bad,
	// 11 reserved and taken as Bad (Part 4, StatusCode).
	if uint32(res.StatusCode)>>31 == 1 {
		return nil, &CallError{Method: m.String(), Status: res.StatusCode, InputArgumentResults: slices.Clone(res.InputArgumentResults)}
	}
	return res.OutputArguments, nil
}
